# Partner (law firm) SEO pages: /partners/<slug>. Targets searches like "lead generation for law firms", "leads for solicitors",
# "immigration law leads". Keep facts in line with legal_partners_content.py: pricing is agreed with each firm, minimum 10 leads a
# month, exclusive to one firm, no platform yet, no PI / clin neg / claims management. No em dashes.

def pg(slug, nav, title, description, h1, summary, sections, faqs, cta_h2='Ready for exclusive client enquiries?'):
    return {'slug': slug, 'nav': nav, 'title': title, 'description': description, 'h1': h1, 'summary': summary,
            'sections': sections, 'faqs': faqs, 'cta_h2': cta_h2}

